"""Semantic Version 2.0.0 parser and total ordering."""
import re

_SEMVER_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$"
)


class InvalidVersionError(ValueError):
    pass


class Version:
    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self.major = int(major)
        self.minor = int(minor)
        self.patch = int(patch)
        self.prerelease = prerelease  # raw string without leading '-' or None
        self.build = build            # raw string without leading '+' or None

    @classmethod
    def parse(cls, text):
        m = _SEMVER_RE.match(text.strip())
        if m is None:
            raise InvalidVersionError("not a valid semver: {!r}".format(text))
        major, minor, patch, prerelease, build = m.groups()
        return cls(major, minor, patch, prerelease=prerelease, build=build)

    @property
    def core(self):
        return (self.major, self.minor, self.patch)

    def _identifiers(self):
        if self.prerelease is None:
            return []
        return [int(x) if x.isdigit() else x for x in self.prerelease.split(".")]

    def _compare(self, other):
        if self.core != other.core:
            return -1 if self.core < other.core else 1
        mine, theirs = self._identifiers(), other._identifiers()

        # A release version has higher precedence than any pre-release.
        # Build metadata is intentionally ignored by SemVer precedence.
        if not mine or not theirs:
            if not mine and not theirs:
                return 0
            return 1 if not mine else -1

        # Compare each pre-release identifier in sequence. Numeric values
        # compare numerically and have lower precedence than alphanumeric
        # identifiers; a shorter otherwise-equal sequence comes first.
        for left, right in zip(mine, theirs):
            if left == right:
                continue
            left_numeric = isinstance(left, int)
            right_numeric = isinstance(right, int)
            if left_numeric and right_numeric:
                return -1 if left < right else 1
            if left_numeric != right_numeric:
                return -1 if left_numeric else 1
            return -1 if left < right else 1

        if len(mine) == len(theirs):
            return 0
        return -1 if len(mine) < len(theirs) else 1

    def __eq__(self, other):
        return isinstance(other, Version) and self._compare(other) == 0

    def __lt__(self, other):
        return self._compare(other) < 0

    def __le__(self, other):
        return self._compare(other) <= 0

    def __gt__(self, other):
        return self._compare(other) > 0

    def __ge__(self, other):
        return self._compare(other) >= 0

    def __hash__(self):
        # Equal versions may differ only in build metadata.
        return hash((self.core, tuple(self._identifiers())))

    def __repr__(self):
        base = "{}.{}.{}".format(self.major, self.minor, self.patch)
        if self.prerelease:
            base += "-" + self.prerelease
        if self.build:
            base += "+" + self.build
        return "Version({})".format(base)
